INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 5, 'theory', 'Quiz: conditions and loops');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 5, 0, 'Which numbers does for i in 1..4 go through?', '["1, 2, 3, 4", "1, 2, 3", "0, 1, 2, 3", "2, 3, 4"]', 1, 'The right bound is not included. To include 4, write 1..=4.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 5, 1, 'What happens with if x { … } where x: i32?', '["it runs if x is not zero", "it runs if x is greater than zero", "compile error: the condition must be bool", "it always runs"]', 2, 'Rust has no "truthy" numbers; write an explicit comparison: if x != 0.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 5, 2, 'What can break value; be used for inside loop?', '["to exit and return the value as the result of the whole loop", "to continue the loop with a new value", "to print the value to the screen", "it can''t: break takes no value"]', 0, 'let r = loop { … break 42; }; — the loop becomes an expression.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 5, 3, 'What does the label ''outer: for … together with break ''outer; do?', '["skips one step of the loop", "nothing, it''s a comment", "makes the loop infinite", "exits the outer loop at once"]', 3, 'Labels let you leave nested loops with a single command.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 5, 4, 'What happens if a match on a u8 does not cover all values and has no _?', '["the program prints a warning", "compile error: patterns are not exhaustive", "the first branch runs on the extra values", "a panic at run time"]', 1, 'match must cover all variants; for the rest write _ => …');
